import{_ as e,o as t,c as r,ai as i}from"./chunks/framework.Ba-VnP44.js";const m=JSON.parse('{"title":"AI 知识库系统","description":"","frontmatter":{},"headers":[],"relativePath":"instances/ai/kb.md","filePath":"instances/ai/kb.md"}'),l={name:"instances/ai/kb.md"};function o(d,a,n,s,c,h){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="ai-知识库系统" tabindex="-1">AI 知识库系统 <a class="header-anchor" href="#ai-知识库系统" aria-label="Permalink to “AI 知识库系统”">​</a></h1><blockquote><p>状态：✅ 已验证（已交付） · 所属模块：<a href="/my-vitepress-site/instances/ai/">01 AI 应用</a> · 模块内优先级：第 1 位 交付位置：<code>E:\\8.cangku\\for-job\\ai-knowledge-base</code></p></blockquote><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to “核心功能”">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>交付说明</th></tr></thead><tbody><tr><td>文档管理</td><td>文档上传、解析（TXT / MD / CSV / JSON）、分块、知识库级联删除</td></tr><tr><td>知识检索</td><td>向量检索 + 关键词混合检索（RRF 融合）、相似度排序、两种模式对比视图</td></tr><tr><td>智能问答</td><td>RAG 问答、SSE 流式输出、多轮追问、引用定位</td></tr><tr><td>来源引用</td><td>答案溯源到原文片段与文档、命中率 + 引用准确率评估报告</td></tr></tbody></table><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to “技术栈”">​</a></h2><ul><li>后端：JDK 21 + Spring Boot 3.3.6 + Maven + H2 + JWT 鉴权</li><li>检索：256 维哈希向量（中文 unigram + bigram，murmur3，L2 归一化）+ 关键词混合召回</li><li>前端：Vue 3.4 + Vite 5 + TypeScript + Element Plus + Pinia + vue-router + markdown-it</li><li>运行端口：后端 <code>8082</code>，前端 <code>5172</code></li></ul><h2 id="关键设计" tabindex="-1">关键设计 <a class="header-anchor" href="#关键设计" aria-label="Permalink to “关键设计”">​</a></h2><ul><li><strong>无答案红线</strong>：相似度低于阈值时拒绝作答（直接回答&quot;不知道&quot;）而不是编造答案；阈值比较的是原始向量余弦分，不是 RRF 融合分</li><li><strong>无密钥降级</strong>：未配置 OpenAI 密钥时自动切换 Mock 生成，保证链路可跑通</li></ul><h2 id="验证证据" tabindex="-1">验证证据 <a class="header-anchor" href="#验证证据" aria-label="Permalink to “验证证据”">​</a></h2><ul><li>单元测试：<strong>199 个测试全部通过</strong>（33 个测试类）</li><li>E2E 测试：<strong>14 / 14 通过</strong>（<code>backend/e2e_kb.py</code>，覆盖知识库创建、文档上传、统计、检索对比、问答引用、无答案拒答、效果评估等全链路）</li><li>交付物：<code>ai-knowledge-base-1.0.0.jar</code> 可执行包、README / API / TEST-REPORT / ARCHITECTURE 文档、<code>sql/schema.sql</code>（6 张表）</li></ul><h2 id="建设状态" tabindex="-1">建设状态 <a class="header-anchor" href="#建设状态" aria-label="Permalink to “建设状态”">​</a></h2><p>✅ 已交付：RAG 全链路（解析-索引-检索-生成-引用）闭环达成，测试与文档齐备。</p><hr><p>上一级：<a href="/my-vitepress-site/instances/ai/">01 AI 应用</a> · <a href="/my-vitepress-site/instances/">实例总览</a></p>',14)])])}const p=e(l,[["render",o]]);export{m as __pageData,p as default};
